def ev(a):
    bad=np.linalg.norm(a-center,axis=1)<0.6
    moved=np.linalg.norm(a-a0,axis=1)>0.3
    off=(np.abs(np.linalg.norm(a,axis=1)-3.2)>0.7).mean()-(np.abs(np.linalg.norm(a0,axis=1)-3.2)>0.7).mean()
    return bad.mean(), (moved&~bad0).mean(), off
def mk(g,T0,T1,lo,hi):
